package com.mahweb.mahyarnfc.omnishare.lan;
import com.mahweb.mahyarnfc.omnishare.transport.DeliveryAck; import java.io.*; import java.nio.charset.StandardCharsets;
public final class DeliveryAckCodec { private DeliveryAckCodec(){} public static byte[] encode(DeliveryAck a){try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);ws(d,a.transferId);ws(d,a.recipientDeviceId);d.writeLong(a.receivedAtEpochMs);d.writeInt(a.signature.length);d.write(a.signature);d.flush();return b.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}} public static DeliveryAck decode(byte[]x)throws IOException{DataInputStream d=new DataInputStream(new ByteArrayInputStream(x));String t=rs(d),r=rs(d);long at=d.readLong();int n=d.readInt();if(n<0||n>4096)throw new IOException("ack signature length");byte[]s=new byte[n];d.readFully(s);if(d.available()!=0)throw new IOException("invalid ack");return new DeliveryAck(t,r,at,s);} private static void ws(DataOutputStream d,String s)throws IOException{byte[]b=(s==null?"":s).getBytes(StandardCharsets.UTF_8);d.writeShort(b.length);d.write(b);} private static String rs(DataInputStream d)throws IOException{int n=d.readUnsignedShort();if(n>4096)throw new IOException("string too long");byte[]b=new byte[n];d.readFully(b);return new String(b,StandardCharsets.UTF_8);} }
